skeleton:
server {
    listen 443 ssl;
    server_name exemple.com;
    root /var/www/spa;

    # 1) proxifier /api/ vers http://backend:8080

    # 2) servir la SPA avec fallback vers index.html
}

solution:
server {
    listen 443 ssl;
    server_name exemple.com;
    root /var/www/spa;

    location /api/ {
        proxy_pass http://backend:8080;
    }

    location / {
        try_files $uri /index.html;
    }
}
